/**
 * Integration Tests - Picker to Execution Pipeline
 *
 * Validates that:
 * 1. Playwright semantic locators generated by the Picker can be executed
 * 2. The full pipeline: Picker selector → buildPlaywrightLocator → Playwright action works
 * 3. AI sanitization preserves locator types correctly
 */
/* global window, document, MouseEvent */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { chromium } from 'playwright';
import {
    buildPlaywrightLocator,
    convertPlaywrightLocator,
    isPlaywrightLocator,
    normalizeSelectorForDotId,
    resolveTarget,
} from '../core/selector-utils.js';
import { startInspector, stopInspector } from '../services/inspector.service.js';

describe('Picker-to-Execution Integration Tests', () => {
    let browser;
    let context;
    let page;

    beforeAll(async () => {
        browser = await chromium.launch({
            headless: true,
            args: ['--no-sandbox', '--disable-dev-shm-usage', '--no-zygote'],
        });
        context = await browser.newContext();
        page = await context.newPage();

        await page.setContent(`
            <html>
                <body>
                    <form id="login-form">
                        <label for="username">Username</label>
                        <input id="username" name="username" placeholder="Enter username" aria-label="Username field">
                        <label for="password">Password</label>
                        <input id="password" name="password" type="password" placeholder="Enter password" aria-label="Password field">
                        <button type="button" data-testid="submit-btn">Login</button>
                        <a href="#" data-testid="forgot-link">Forgot password?</a>
                        <img src="test.png" alt="Company Logo" title="Company home">
                    </form>
                    <div role="dialog" aria-label="Checkout">
                        <button>Save</button>
                        <button>Save</button>
                    </div>
                </body>
            </html>
        `);
        await page.waitForLoadState('domcontentloaded');
    });

    afterAll(async () => {
        if (context) await context.close().catch(() => {});
        if (browser) await browser.close().catch(() => {});
    });

    describe('buildPlaywrightLocator', () => {
        it('should execute getByTestId', async () => {
            const locator = buildPlaywrightLocator(page, "getByTestId('submit-btn')");
            console.log('getByTestId locator:', locator.constructor?.name || typeof locator);
            await locator.click({ timeout: 3000, force: true });
            expect(true).toBe(true);
        });

        it('should execute getByRole with name', async () => {
            const locator = buildPlaywrightLocator(page, "getByRole('button', { name: 'Login' })");
            console.log('getByRole locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.click({ timeout: 3000, force: true });
            expect(true).toBe(true);
        });

        it('should execute getByLabel', async () => {
            const locator = buildPlaywrightLocator(page, "getByLabel('Username')");
            console.log('getByLabel locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.fill('testuser', { timeout: 3000, force: true });
            const value = await locator.inputValue();
            expect(value).toBe('testuser');
        });

        it('should execute getByPlaceholder', async () => {
            const locator = buildPlaywrightLocator(page, "getByPlaceholder('Enter password')");
            console.log('getByPlaceholder locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.fill('secret123', { timeout: 3000, force: true });
            const value = await locator.inputValue();
            expect(value).toBe('secret123');
        });

        it('should execute getByText', async () => {
            const locator = buildPlaywrightLocator(page, "getByText('Forgot password?')");
            console.log('getByText locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.click({ timeout: 3000, force: true });
            expect(true).toBe(true);
        });

        it('should execute getByAltText', async () => {
            const locator = buildPlaywrightLocator(page, "getByAltText('Company Logo')");
            console.log('getByAltText locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.click({ timeout: 3000, force: true });
            expect(true).toBe(true);
        });

        it('should execute getByTitle', async () => {
            const locator = buildPlaywrightLocator(page, "getByTitle('Company home')");
            console.log('getByTitle locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.click({ timeout: 3000, force: true });
            expect(true).toBe(true);
        });

        it('should execute getByRole without name', async () => {
            const locator = buildPlaywrightLocator(page, "getByRole('link')");
            console.log('getByRole link locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.click({ timeout: 3000, force: true });
            expect(true).toBe(true);
        });

        it('should fallback to CSS selector', async () => {
            const locator = buildPlaywrightLocator(page, '#username');
            console.log('CSS locator:', locator.constructor?.name || typeof locator);
            const count = await locator.count();
            console.log('Count:', count);
            await locator.fill('cssuser', { timeout: 3000, force: true });
            const value = await locator.inputValue();
            expect(value).toBe('cssuser');
        });
    });

    describe('convertPlaywrightLocator', () => {
        it('should preserve Playwright locator strings', () => {
            expect(convertPlaywrightLocator("getByTestId('foo')")).toBe("getByTestId('foo')");
            expect(convertPlaywrightLocator("getByLabel('foo')")).toBe("getByLabel('foo')");
            expect(convertPlaywrightLocator("getByAltText('foo')")).toBe("getByAltText('foo')");
            expect(convertPlaywrightLocator("getByTitle('foo')")).toBe("getByTitle('foo')");
            expect(convertPlaywrightLocator('#css')).toBe('#css');
        });
    });

    describe('isPlaywrightLocator', () => {
        it('recognises bare, namespaced and chained getBy* locators', () => {
            expect(isPlaywrightLocator("getByText('Submit')")).toBe(true);
            expect(isPlaywrightLocator("getByRole('button', { name: 'Save' })")).toBe(true);
            expect(isPlaywrightLocator("page.getByRole('link')")).toBe(true);
            expect(isPlaywrightLocator("page.locator('#form').getByLabel('Email')")).toBe(true);
        });

        it('rejects CSS, XPath and non-string values', () => {
            expect(isPlaywrightLocator('#showOverview')).toBe(false);
            expect(isPlaywrightLocator('div > button')).toBe(false);
            expect(isPlaywrightLocator('//div[@id="showOverview"]')).toBe(false);
            expect(isPlaywrightLocator('')).toBe(false);
            expect(isPlaywrightLocator(null)).toBe(false);
            expect(isPlaywrightLocator(undefined)).toBe(false);
        });
    });

    describe('normalizeSelectorForDotId', () => {
        it('should pass through non-CSS selectors', async () => {
            const result = await normalizeSelectorForDotId(page, "getByTestId('foo')");
            expect(result).toBe("getByTestId('foo')");
        });

        it('should normalize dot-id CSS selectors when needed', async () => {
            const result = await normalizeSelectorForDotId(page, '#username.test');
            expect(result).toBe('#username.test');
        });
    });

    describe('Ambiguous locator resolution', () => {
        it('should mark duplicate role locators as ambiguous in metadata', async () => {
            const matchCount = 2;
            expect(matchCount).toBeGreaterThan(1);
        });

        it('should find unique button with context', async () => {
            const locator = buildPlaywrightLocator(page, "getByRole('button', { name: 'Login' })");
            const count = await locator.count();
            expect(count).toBe(1);
        });

        it('should execute chained locator with context', async () => {
            const locator = buildPlaywrightLocator(
                page,
                "page.getByRole('dialog', { name: 'Checkout' }).getByRole('button', { name: 'Save' })",
            );
            const count = await locator.count();
            expect(count).toBe(2);
        });
    });

    describe('Fill form field Playwright locators', () => {
        it('should fill a field using getByLabel', async () => {
            const locator = buildPlaywrightLocator(page, "getByLabel('Username')");
            await locator.fill('picker-user', { timeout: 3000, force: true });
            const value = await locator.inputValue();
            expect(value).toBe('picker-user');
        });

        it('should fill a field using getByPlaceholder', async () => {
            const locator = buildPlaywrightLocator(page, "getByPlaceholder('Enter password')");
            await locator.fill('picker-pass', { timeout: 3000, force: true });
            const value = await locator.inputValue();
            expect(value).toBe('picker-pass');
        });

        it('should fill a field using chained context locator', async () => {
            const locator = buildPlaywrightLocator(
                page,
                "page.locator('#login-form').getByLabel('Username')",
            );
            await locator.fill('chained-user', { timeout: 3000, force: true });
            const value = await locator.inputValue();
            expect(value).toBe('chained-user');
        });
    });

    describe('Ambiguous getByText resolution (strict mode)', () => {
        it('resolves and clicks a single element when getByText matches multiple', async () => {
            const p = await context.newPage();
            await p.setContent(`
                <html><body>
                    <p>If closed, it will not appear on subsequent page loads.</p>
                    <p id="modal-close" onclick="this.dataset.clicked='1'">Close</p>
                </body></html>
            `);

            // The picker emits the substring getByText; Playwright resolves it
            // to TWO paragraphs (strict mode violation for single-element actions).
            const raw = buildPlaywrightLocator(p, "getByText('Close')");
            expect(await raw.count()).toBe(2);

            // Persisted target carries the substring primary plus an
            // unambiguous cssPath candidate. Resolution must skip the
            // ambiguous selector and use the candidate, so click() works.
            const target = {
                selector: "getByText('Close')",
                scope: 'element',
                selectorType: 'playwrightText',
                candidates: {
                    playwrightText: "getByText('Close')",
                    cssPath: '#modal-close',
                },
            };
            const resolution = await resolveTarget({
                page: p,
                target,
                scope: 'element',
                timeout: 5000,
            });
            expect(resolution.resolution).toBe('fallback');
            expect(resolution.usedSelector).toBe('#modal-close');
            expect(resolution.candidatesTried[0].status).toBe('ambiguous');

            await resolution.locator.click();
            await expect
                .poll(() => p.locator('#modal-close').getAttribute('data-clicked'))
                .toBe('1');
            await p.close();
        });
    });

    describe('In-page picker prioritizes Playwright locators', () => {
        const pickOnPage = async (html, elementId = 'target') => {
            const p = await context.newPage();
            await p.setContent(`<html><body>${html}</body></html>`);
            await p.waitForLoadState('domcontentloaded');

            await startInspector(p);

            await p.evaluate(() => {
                window.__captured = [];
                const orig = window.onElementSelected;
                window.onElementSelected = (data) => {
                    window.__captured.push(data);
                    return orig(data);
                };
            });

            await p.evaluate((id) => {
                document
                    .getElementById(id)
                    .dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
            }, elementId);

            await expect.poll(() => p.evaluate(() => window.__captured.length)).toBe(1);
            const data = await p.evaluate(() => window.__captured[0]);
            await stopInspector(p).catch(() => {});
            await p.close();
            return data;
        };

        it('prefers getByText over the id selector for a div with text', async () => {
            const data = await pickOnPage(`<div id="target">Show Overview</div>`);
            expect(data.selector).toBe("getByText('Show Overview')");
            expect(data.selectorType).toBe('playwrightText');
            expect(data.candidates.id).toBe('#target');
            expect(data.ambiguous).toBe(false);
        });

        it('prefers getByRole over the id selector for a button with text', async () => {
            const data = await pickOnPage(`<button id="target">Show Overview</button>`);
            expect(data.selector).toBe("getByRole('button', { name: 'Show Overview' })");
            expect(data.selectorType).toBe('playwrightRole');
            expect(data.candidates.id).toBe('#target');
        });

        it('prefers getByTestId over the id selector', async () => {
            const data = await pickOnPage(
                `<div id="target" data-testid="overview">Show Overview</div>`,
            );
            expect(data.selector).toBe("getByTestId('overview')");
            expect(data.selectorType).toBe('playwrightTestId');
            expect(data.candidates.id).toBe('#target');
        });

        it('falls back to the id selector only when no Playwright locator exists', async () => {
            const data = await pickOnPage(`<div id="target"></div>`);
            expect(data.selector).toBe('#target');
            expect(data.selectorType).toBe('id');
            expect(data.candidates.playwrightText).toBeUndefined();
            expect(data.candidates.playwrightRole).toBeUndefined();
        });
    });
});
